import{z as d,x as m,o as n,c,q as E,j as s,D as r,d as a,s as i,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"rename 原子性","description":"","frontmatter":{"title":"rename 原子性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rename-atomicity.md","filePath":"cs/rename-atomicity.md","lastUpdated":1791063341000}'),A={name:"cs/rename-atomicity.md"};function p(f,e,B,u,D,h){const t=m("Mermaid");return n(),c("div",null,[e[2]||(e[2]=E('<h1 id="rename-原子性" tabindex="-1">rename 原子性 <a class="header-anchor" href="#rename-原子性" aria-label="Permalink to &quot;rename 原子性&quot;">​</a></h1><div class="epigraph"><p>POSIX rename 要求：同一文件系统内，新名字要么完全指向新对象，要么仍是旧的；读者不应看见「两个名字都没有」的中间态。</p><footer>—— 据 POSIX rename；McKusick 对目录项更新与崩溃的讨论；ext4 对 rename 进事务的实践</footer></div><p><a href="/cs/inotify">上一课</a>把 rename 当成一对 cookie 事件。应用更关心：<strong>替换配置文件</strong>时，读者打开的是完整旧文件或完整新文件。缺口是 rename 的原子性与其实现依赖——目录项、链接计数、跨目录、跨 FS 失败。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写 <code>foo.tmp</code> 再 <code>rename(foo.tmp, foo)</code> 是经典发布手法：查找 <code>foo</code> 的人不应落到半截内容。POSIX：同挂载内 rename 覆盖已存在目标（非目录）是原子替换。跨设备返回 <code>EXDEV</code>，用户态才拷贝。缺口：内核如何把「删旧目录项、加新目录项、调整 <code>..</code>、减目标链接」收成一块；<a href="/cs/ext4-journal">日志</a> 与 <a href="/cs/cow-filesystem">COW</a> 如何保证崩溃后不是半改；软更新如何排序这两项。</p><p><span class="marginnote">目录 rename 还要改子目录 <code>..</code>，并防止把目录挂到自己的子孙下。whiteout 与 overlay 的 rename 另有规则，本课先钉底层 FS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ext4：rename 参加 JBD2 事务，目录块与 inode 一起提交。btrfs：新树根同时包含两项更新。无日志 FAT：两步目录项更新，崩溃可丢名或双名，靠 <a href="/cs/fsck">fsck</a>。VFS 先锁参与的目录 inode（锁序避免死锁），再调具体 <code>rename</code>。读者 lookup 要么看见旧 dentry 要么新的——<a href="/cs/dcache">dcache</a> 在事务/锁下更新。</p><p><span class="marginnote">直觉类比：写临时文件再 rename，像剧场换布景时用一块「幕布时刻」完成切换——观众（lookup）要么看到旧布景，要么看到新布景，绝看不到半拉起的空架子。直接在 <code>foo</code> 上打开写，则是当着观众的面拆台。</span></p><p><span class="marginnote">常见误区：「rename 是原子的」不等于「新文件已可靠落盘」。目录项切换是原子的，但若忘记先对临时文件 <code>fsync</code>，崩溃后可能出现「新名字指向空文件或不存在」——正确顺序是先 fsync 内容、再 rename、再 fsync 目录。</span></p>',10)),(n(),s(l,null,{default:r(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22rename%20A%20to%20B%22%5D%20--%3E%20LOCK%5B%22%E9%94%81%E5%8F%82%E4%B8%8E%E7%9B%AE%E5%BD%95%22%5D%0A%20%20LOCK%20--%3E%20TX%5B%22FS%20%E4%BA%8B%E5%8A%A1%E6%88%96%20COW%20%E6%A0%B9%22%5D%0A%20%20TX%20--%3E%20VIS%5B%22lookup%20%E5%8F%AA%E8%A7%81%E6%97%A7%E6%88%96%E6%96%B0%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,[a("rename 原子性把「发布」从字节拷贝里解放出来：内容早已 fsync 在临时 inode 上，名字切换才是可见点。它不保证跨文件的多对象原子（那要更上层事务）。不要把本课写成数据库 "),o("code",null,"UPDATE"),a(" 的 MVCC：对象是目录项。")],-1)),e[5]||(e[5]=o("p",null,[a("与 "),o("a",{href:"/cs/nfs-semantics"},"NFS"),a("：远程 rename 的原子性取决于服务器；客户端缓存可能短暂看见旧名。与 inotify：原子替换仍可能产生 DELETE+CREATE 或 MOVED_*，应用不能假设只有一种事件形状。")],-1)),e[6]||(e[6]=o("p",null,[a("实现上：跨目录 rename 要锁两个目录，锁序按 inode 号避免死锁。目标若是非空目录，POSIX 失败；覆盖文件则减链接，可能把还打开的 inode 变成匿名。 读法上只引用"),o("a",{href:"/cs/inotify"},"上一课"),a("的结论，不把对象换成训练推理或限价簿。")],-1)),(n(),s(l,null,{default:r(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%20foo.tmp%20%E5%B9%B6%20fsync%22%5D%20--%3E%20R%5B%22rename%20foo.tmp%2C%20foo%22%5D%0A%20%20R%20--%3E%20FSY%5B%22fsync%20%E7%9B%AE%E5%BD%95%E9%A1%B9%22%5D%0A%20%20FSY%20--%3E%20GOOD%5B%22%E5%B4%A9%E6%BA%83%E5%90%8E%20foo%20%E5%BF%85%E4%B8%BA%E5%AE%8C%E6%95%B4%E6%96%B0%E5%86%85%E5%AE%B9%22%5D%0A%20%20BAD%5B%22%E7%9B%B4%E6%8E%A5%E5%86%99%20foo%20%E6%9C%AC%E4%BD%93%22%5D%20--%3E%20H1%5B%22%E5%B4%A9%E6%BA%83%E7%AA%97%E5%8F%A3%3A%20%E6%96%87%E4%BB%B6%E5%8D%8A%E6%96%B0%E5%8D%8A%E6%97%A7%22%5D%0A%20%20H1%20--%3E%20READER%5B%22%E8%AF%BB%E8%80%85%E5%8F%AF%E8%83%BD%E8%AF%BB%E5%88%B0%E6%88%AA%E6%96%AD%E5%86%85%E5%AE%B9%22%5D%0A%20%20GOOD%20-.%E5%AF%B9%E6%AF%94.-%3E%20READER%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=E('<p>这张图回答的问题是「发布一个配置文件，正确路径和错误路径差在哪一步」：差别全在「名字切换是否是唯一可见点」。走 rename 的路径，崩溃只会回退到旧内容或前进到新内容；直接覆盖的路径，崩溃点落在哪个字节是不可控的。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>rename 原子性</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>renameat2</code> 的 <code>RENAME_EXCHANGE</code>/<code>NOREPLACE</code> 全部标志当考纲，只承认它们改变失败条件，不改变「成功则原子」。下一课看不必落盘的树：tmpfs。</p><p>版本字段会变，课序钉的是机制对象「rename 原子性」，不是某一主线内核的结构体名。 后课默认：同 FS 内 rename 是名字发布点。纯内存文件系统如何实现同一套 VFS 操作，下一课 tmpfs。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同挂载 rename 对 lookup 原子；跨设备 EXDEV。</li><li>实现靠日志事务、COW 根或谨慎写序。</li><li>内存 FS 是下一课。</li><li>出处：POSIX；McKusick；ext4/btrfs rename 路径；<em>OSTEP</em>。</li></ul>',8))])}const _=d(A,[["render",p]]);export{T as __pageData,_ as default};
